                headers["Content-Type"] = "application/xml"
                return requests.post(
                    p.urls["transporte"] + path,
                    data=request_xml(data).encode(),
                    headers=headers,
                    timeout=20,
                )
            return requests.post(
                p.urls["transporte"] + path, json=data, headers=headers, timeout=20
            )

